"""The IPFS launcher block that goes into every mint HTML (see README.md, "Launcher behaviour").

Two pieces are swapped into a base HTML (Transient's kit file, or an already minted
medium_nNN.html): the GATEWAY_TEMPLATES list and the launchFromIpfs() function.
apply_launcher() is idempotent, so it can be run on a base that already has them.
"""
import re

GATEWAYS = '      const GATEWAY_TEMPLATES = [\n        "https://ipfs.filebase.io/ipfs/{cid}/",\n        "https://gateway.pinata.cloud/ipfs/{cid}/",\n        "https://ipfs.4everland.io/ipfs/{cid}/",\n        "https://ipfs2.seadn.io/ipfs/{cid}/",\n        "https://ipfs.transientusercontent.xyz/ipfs/{cid}/",\n        "https://ipfs.io/ipfs/{cid}/",\n      ];\n'

LAUNCHER = "(async function launchFromIpfs() {\n        if (!ARTWORK_CID || ARTWORK_CID === 'PASTE_FOLDER_CID_HERE' || /[\\s/]/.test(ARTWORK_CID)) {\n          showLaunchError('Setup required: replace PASTE_FOLDER_CID_HERE with the IPFS folder CID.');\n          return;\n        }\n\n        // Gateways are tried in order (Filebase first: it serves from storage we\n        // control). Public gateways sometimes answer cold requests with a 429/5xx\n        // that has no CORS header, which the browser reports as a CORS error.\n        // So every request below can fail over to the next gateway.\n        const bases = GATEWAY_TEMPLATES.map((template) =>\n          template.replace('{cid}', encodeURIComponent(ARTWORK_CID))\n        );\n        const PROBE_MS = 8000;\n        const ASSET_MS = 30000;\n        const sleep = (ms) => new Promise((r) => setTimeout(r, ms));\n        const origFetch = window.fetch.bind(window);\n\n        async function fetchTimed(url, init, ms) {\n          const controller = new AbortController();\n          const timer = setTimeout(() => controller.abort(), ms);\n          try {\n            return await origFetch(url, Object.assign({}, init, { signal: controller.signal }));\n          } finally {\n            clearTimeout(timer);\n          }\n        }\n\n        // 1. Pick a gateway that serves the manifest AND a real shader file.\n        const failures = [];\n        for (const base of bases) {\n          try {\n            const response = await fetchTimed(new URL(SCENE_FILE, base), { cache: 'no-store' }, PROBE_MS);\n            if (!response.ok) throw new Error('HTTP ' + response.status);\n            const scene = await response.json();\n            if (!scene || (!scene.frag && !scene.vert && !scene.geometry)) {\n              throw new Error('scene.json is not a scene manifest');\n            }\n            const probe = scene.vert || scene.frag;\n            if (probe) {\n              const r = await fetchTimed(new URL((scene.prefix || '') + probe, base), { cache: 'no-store' }, PROBE_MS);\n              if (!r.ok) throw new Error('shader HTTP ' + r.status);\n              await r.arrayBuffer();\n            }\n            window.IPFS_ASSET_BASE = base;\n            break;\n          } catch (error) {\n            failures.push(base + ' — ' + (error.name === 'AbortError' ? 'timeout' : error.message));\n          }\n        }\n\n        if (!window.IPFS_ASSET_BASE) {\n          showLaunchError('No IPFS gateway could load the artwork.\\n' + failures.join('\\n'));\n          return;\n        }\n\n        // Selected gateway first, then the rest.\n        const ordered = [window.IPFS_ASSET_BASE].concat(bases.filter((b) => b !== window.IPFS_ASSET_BASE));\n\n        // 2. Any request for an artwork file (shaders, textures, wasm, boot.js\n        // internals) is retried on the next gateway if it fails.\n        window.fetch = async function (input, init) {\n          const url = typeof input === 'string' ? input : (input && input.url) || String(input);\n          const method = ((init && init.method) || (input && input.method) || 'GET').toUpperCase();\n          const base = bases.find((b) => url.startsWith(b));\n          if (!base || method !== 'GET') return origFetch(input, init);\n          const rel = url.slice(base.length);\n          let last;\n          for (let round = 0; round < 2; round++) {\n            for (const b of ordered) {\n              try {\n                const r = await fetchTimed(b + rel, init && init.signal ? Object.assign({}, init, { signal: undefined }) : init, ASSET_MS);\n                if (r.ok) return r;\n                last = r;\n              } catch (e) {\n                last = e;\n              }\n            }\n            await sleep(600);\n          }\n          if (last instanceof Response) return last;\n          throw last;\n        };\n\n        // <script> and import() don't use fetch, so give them the same failover.\n        function loadScriptFrom(i, path) {\n          return new Promise((resolve, reject) => {\n            const s = document.createElement('script');\n            s.src = new URL(path, ordered[i]).href;\n            s.onload = resolve;\n            s.onerror = () => {\n              s.remove();\n              if (i + 1 < ordered.length) loadScriptFrom(i + 1, path).then(resolve, reject);\n              else reject(new Error('Could not load ' + path));\n            };\n            document.head.appendChild(s);\n          });\n        }\n        async function importFrom(path) {\n          let err;\n          for (const b of ordered) {\n            try { return await import(new URL(path, b).href); } catch (e) { err = e; }\n          }\n          throw err;\n        }\n\n        const assetUrl = (path) => new URL(path, window.IPFS_ASSET_BASE).href;\n        const poster = document.getElementById('poster');\n        poster.poster = assetUrl(POSTER_IMAGE);\n        poster.querySelector('source').src = assetUrl(POSTER_VIDEO);\n        poster.load();\n\n        try {\n          await loadScriptFrom(0, 'glslViewer.js');\n          await importFrom('boot.js');\n        } catch (error) {\n          showLaunchError('Artwork startup failed: ' + error.message);\n        }\n      })();"

_GW_RE = re.compile(r'      const GATEWAY_TEMPLATES = \[.*?\n      \];\n', re.S)
_L_RE = re.compile(r'\(async function launchFromIpfs\(\) \{.*?\n      \}\)\(\);', re.S)


def apply_launcher(html):
    assert len(_GW_RE.findall(html)) == 1 and len(_L_RE.findall(html)) == 1, 'launcher block not found in base HTML'
    html = _GW_RE.sub(lambda m: GATEWAYS, html)
    return _L_RE.sub(lambda m: LAUNCHER, html)
